// Run tests in the repository
const workdir = $json.workdir || '/workspace';
const testCmd = $json.testCmd || 'npm test';

return [{ json: {
  action: 'agent_launch',
  prompt: `Run tests: ${testCmd} in ${workdir}. Report all failures.`, 
  name: 'test-run-' + Date.now(),
  workdir: workdir,
  config: { permission_mode: 'plan', plan_approval: 'delegate', worktree_strategy: 'delegate' }
}}];

// Check test results
const sessionId = $json.sessionId;
return [{ json: { sessionId, action: 'get_output' } }];

// Launch fix agent for failing tests
const sessionId = $json.sessionId;
return [{ json: {
  action: 'agent_launch',
  prompt: 'Fix failing tests based on output: ' + $json.output,
  name: 'test-fix-' + Date.now(),
  workdir: $json.workdir,
  config: { permission_mode: 'plan', plan_approval: 'delegate', worktree_strategy: 'delegate' }
}}];
